// ---------------------------------------------------------------------------
// --- a macro with an empty name
//     expands without calling a function on the block

export type TTextBlock = {
	type: 'text'
	firstLine: string
	lContent: TBlock[]
	}

export type TMacroBlock = {
	type: 'macro'
	name: string
	args: string
	lContent: TBlock[]
	}

export type TBlock = TTextBlock | TMacroBlock

// ---------------------------------------------------------------------------

export const mkBlk = (
		firstLine: string,
		...lOrgContent: (TTextBlock | TMacroBlock | string)[]
		): TTextBlock | TMacroBlock => {


	const lContent = mkArray(lOrgContent, function*(x) {
		if (isString(x)) {
			yield {
				type: 'text',
				firstLine: x,
				lContent: []
				}
		}
		else {
			yield x
		}
	})

	const lMatches = firstLine.match(/^\#([A-Za-z_][A-Za-z0-9_]*)\s*(.*)$/)

	if (defined(lMatches)) {
		return {
			type: 'macro',
			name: lMatches[1],
			args: lMatches[2],
			lContent
			} as TMacroBlock
	}
	else {
		return {
			type: 'text',
			firstLine,
			lContent
			} as TTextBlock
	}
}


// ---------------------------------------------------------------------------

export type TMacroFunc = (
		block: string,
		args: string
		) => string

export type TMacroLib = hashof<TMacroFunc>

export const isMacroLib = (x: unknown): x is TMacroLib => {

	if (!isHash(x)) {
		return false
	}
	let i = 0;for (const _ of entries(x)) {const macro = i++;
		if (!isStringMapper(macro)) {
			return false
		}
	}
	return true
}

// ---------------------------------------------------------------------------

export const expand = (
		lContent: TBlock[],
		hMacros: TMacroLib
		): string => {

	const lParts = mkArray(lContent, function*(x) {
		switch(x.type) {
			case 'text': {
				yield x.firstLine
				if (nonEmpty(x.lContent)) {
					yield indented(expand(x.lContent, hMacros))
				};break;
			}
			case 'macro': {
				const func = hMacros[x.name]
				yield func(expand(x.lContent, hMacros), x.args);break;
			}
		}
	})

	return toBlock(lParts)
}

// ---------------------------------------------------------------------------
// ASYNC

export const mapString = async (
		text: string,
		hMacros: TMacroLib
		): AutoPromise<string> => {

	const lBlocks: TBlock[] = await parseText('macros', text)
	return toBlock(expand(lBlocks, hMacros))
}

// ---------------------------------------------------------------------------
// ASYNC

export const mapFile = async (
		path: string,
		hMacros: TMacroLib
		): AutoPromise<string> => {

	const {ext} = parsePath(path)
	assert(defined(ext) && ext.startsWith('.$'),
		`Not a macro file: ${path}`)
	const [hMetaData, text] = await openTextFile(path, true)
	return await mapString(text, hMacros)
}

